import React, { useRef } from 'react';
import { Upload, X, Image as ImageIcon } from 'lucide-react';
import { FileData } from '../types';

interface FileUploadProps {
  label: string;
  subLabel?: string;
  accept?: string;
  multiple?: boolean;
  maxFiles?: number;
  files: FileData[];
  onFilesChange: (files: FileData[]) => void;
  className?: string;
}

export const FileUpload: React.FC<FileUploadProps> = ({
  label,
  subLabel,
  accept = "image/*",
  multiple = false,
  maxFiles = 1,
  files,
  onFilesChange,
  className = ""
}) => {
  const inputRef = useRef<HTMLInputElement>(null);

  const handleFileChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files && e.target.files.length > 0) {
      const newFiles: File[] = Array.from(e.target.files);

      const processFiles = async () => {
        const processedFiles: FileData[] = await Promise.all(
          newFiles.map(async (file) => {
            return new Promise<FileData>((resolve, reject) => {
              const reader = new FileReader();
              reader.readAsDataURL(file);
              reader.onload = () => resolve({
                id: Math.random().toString(36).substr(2, 9),
                url: URL.createObjectURL(file),
                file,
                base64: (reader.result as string).split(',')[1] // Remove data prefix
              });
              reader.onerror = error => reject(error);
            });
          })
        );

        if (multiple) {
          const combined = [...files, ...processedFiles].slice(0, maxFiles);
          onFilesChange(combined);
        } else {
          onFilesChange([processedFiles[0]]);
        }
      };

      processFiles();
      // Reset input
      if (inputRef.current) inputRef.current.value = '';
    }
  };

  const removeFile = (id: string) => {
    onFilesChange(files.filter(f => f.id !== id));
  };

  return (
    <div className={`w-full ${className}`}>
      <div className="flex justify-between items-end mb-2">
        <label className="block text-sm font-bold text-charcoal uppercase tracking-wider">{label}</label>
        {subLabel && <span className="text-xs text-gray-500 italic">{subLabel}</span>}
      </div>

      <div 
        className="border-2 border-dashed border-gray-300 rounded-lg p-6 hover:border-gold-400 hover:bg-gold-50 transition-colors cursor-pointer flex flex-col items-center justify-center min-h-[160px]"
        onClick={() => inputRef.current?.click()}
      >
        <input 
          ref={inputRef}
          type="file" 
          accept={accept} 
          multiple={multiple} 
          className="hidden" 
          onChange={handleFileChange}
        />

        <div className="bg-gray-100 p-3 rounded-full mb-3">
          <Upload className="w-6 h-6 text-gray-600" />
        </div>
        <p className="text-sm text-gray-600 font-medium">Click to upload</p>
        <p className="text-xs text-gray-400 mt-1">
          {multiple ? `Up to ${maxFiles} images` : 'Single image'}
        </p>
      </div>

      {files.length > 0 && (
        <div className="mt-4 grid grid-cols-2 sm:grid-cols-3 gap-3">
          {files.map(file => (
            <div key={file.id} className="relative group aspect-video bg-gray-100 rounded-md overflow-hidden border border-gray-200">
              <img src={file.url} alt="preview" className="w-full h-full object-cover" />
              <button 
                onClick={() => removeFile(file.id)}
                className="absolute top-1 right-1 bg-red-500 text-white rounded-full p-1 opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <X className="w-3 h-3" />
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
};

import { GoogleGenAI } from "@google/genai";
import { StyleDirection, FileData } from "../types";
import { SYSTEM_ROLE, ARCHITECTURAL_CONSTRAINTS, EDIT_SYSTEM_ROLE } from "../constants";

export const generateDesignForStyle = async (
  style: StyleDirection,
  targetImage: FileData,
  brandImages: FileData[],
  userPrompt: string
): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Construct the prompt
    const styleDescription = style.description.join('\n- ');

    const promptText = `
${SYSTEM_ROLE}

INPUT CONTEXT:
1. The FIRST image provided is the TARGET CORRIDOR structure.
2. The SUBSEQUENT images are BRAND REFERENCE style guides.

${ARCHITECTURAL_CONSTRAINTS}

STEP 3 — DESIGN TASK
Redesign the target corridor using the brand identity found in the reference images.

APPLY THIS SPECIFIC STYLE DIRECTION:
**${style.title.toUpperCase()}**
- ${styleDescription}

USER EDIT PROMPT (Apply intelligently):
"${userPrompt}"

STEP 6 — OUTPUT REQUIREMENTS (CRITICAL)
- Output EXACTLY 1 photorealistic image
- Keep the SAME camera angle as the original corridor
- No text, labels, or watermarks inside images
- Ultra-realistic lighting, materials, and shadows
- Hotel brochure / investor presentation quality
    `;

    const parts: any[] = [];

    // 1. Add Target Image (Structure)
    parts.push({
      inlineData: {
        data: targetImage.base64,
        mimeType: targetImage.file.type || 'image/png'
      }
    });

    // 2. Add Brand Images (Style References)
    brandImages.forEach(img => {
      parts.push({
        inlineData: {
          data: img.base64,
          mimeType: img.file.type || 'image/png'
        }
      });
    });

    // 3. Add Text Prompt
    parts.push({ text: promptText });

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: parts
      },
      config: {
        imageConfig: {
          imageSize: "2K", // High quality for architecture
          aspectRatio: "16:9" // Or infer from image, but 16:9 is safe for cinematic corridor shots
        }
      }
    });

    // Extract image
    // Note: The response might contain multiple parts, we look for inlineData
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("No image generated in response.");

  } catch (error) {
    console.error(`Error generating design for ${style.title}:`, error);
    throw error;
  }
};

export const editDesign = async (
  imageBase64: string,
  editPrompt: string
): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview', // High quality for professional edits
      config: {
        systemInstruction: EDIT_SYSTEM_ROLE,
        imageConfig: {
          imageSize: "2K",
        }
      },
      contents: {
        parts: [
          {
            inlineData: {
              data: imageBase64,
              mimeType: 'image/png',
            },
          },
          {
            text: `USER EDIT PROMPT: ${editPrompt}`,
          },
        ],
      },
    });

    // Extract image
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("No image generated in response.");
  } catch (error) {
    console.error("Error editing design:", error);
    throw error;
  }
};

