import React, { useState, useEffect } from 'react';
import { FileUpload } from './components/FileUpload';
import { Button } from './components/Button';
import { DesignGallery } from './components/DesignGallery';
import { HistorySection } from './components/HistorySection';
import { QuickEditSection } from './components/QuickEditSection';
import { FileData, GeneratedDesign, DesignSession } from './types';
import { STYLE_DIRECTIONS } from './constants';
import { generateDesignForStyle } from './services/geminiService';
import { Palette, Key, ShieldCheck, Info } from 'lucide-react';

const HISTORY_KEY = 'lumina_history_v1';

const App: React.FC = () => {
  // State
  const [apiKeySelected, setApiKeySelected] = useState<boolean>(false);
  const [targetImage, setTargetImage] = useState<FileData[]>([]);
  const [brandImages, setBrandImages] = useState<FileData[]>([]);
  const [userPrompt, setUserPrompt] = useState<string>('');

  const [isGenerating, setIsGenerating] = useState<boolean>(false);
  const [designs, setDesigns] = useState<GeneratedDesign[]>([]);
  const [history, setHistory] = useState<DesignSession[]>([]);

  // Check for API Key on mount and Load History
  useEffect(() => {
    checkApiKey();
    loadHistory();
  }, []);

  const checkApiKey = async () => {
    if (window.aistudio && window.aistudio.hasSelectedApiKey) {
      const hasKey = await window.aistudio.hasSelectedApiKey();
      setApiKeySelected(hasKey);
    }
  };

  const loadHistory = () => {
    try {
      const saved = localStorage.getItem(HISTORY_KEY);
      if (saved) {
        setHistory(JSON.parse(saved));
      }
    } catch (e) {
      console.error("Failed to load history", e);
    }
  };

  const saveToHistory = (newSession: DesignSession) => {
    try {
      // Create new history array
      let updatedHistory = [newSession, ...history];

      // Try to save. If quota exceeded, remove oldest items until it fits
      while (updatedHistory.length > 0) {
        try {
          localStorage.setItem(HISTORY_KEY, JSON.stringify(updatedHistory));
          setHistory(updatedHistory);
          break; // Success
        } catch (e: any) {
          if (e.name === 'QuotaExceededError' || e.code === 22) {
             // Remove the last item (oldest) and try again
             if (updatedHistory.length > 1) {
               updatedHistory.pop();
             } else {
               // Cannot save even one item, give up
               console.warn("Storage full, cannot save new design session.");
               break;
             }
          } else {
            throw e; // Unknown error
          }
        }
      }
    } catch (e) {
      console.error("History save failed:", e);
    }
  };

  const handleDeleteHistory = (id: string) => {
    const updated = history.filter(h => h.id !== id);
    setHistory(updated);
    localStorage.setItem(HISTORY_KEY, JSON.stringify(updated));
  };

  const handleSelectKey = async () => {
    if (window.aistudio && window.aistudio.openSelectKey) {
      await window.aistudio.openSelectKey();
      // Assume success as per race condition instructions
      setApiKeySelected(true);
    }
  };

  const handleGenerate = async () => {
    if (!apiKeySelected) {
      await handleSelectKey();
    }

    // Check again just in case, though we assume flow continues
    if (targetImage.length === 0) return;

    setIsGenerating(true);

    // Initialize placeholders
    const initialDesigns: GeneratedDesign[] = STYLE_DIRECTIONS.map(style => ({
      id: Math.random().toString(),
      styleId: style.id,
      styleTitle: style.title,
      imageUrl: '',
      status: 'pending'
    }));
    setDesigns(initialDesigns);

    // Process sequentially to show progress and avoid rate limits
    // We create a local copy to track completed designs for history saving
    let completedDesigns: GeneratedDesign[] = [...initialDesigns];
    let hasFailures = false;

    for (let i = 0; i < STYLE_DIRECTIONS.length; i++) {
      const style = STYLE_DIRECTIONS[i];

      // Update status to generating
      setDesigns(prev => prev.map(d => 
        d.styleId === style.id ? { ...d, status: 'generating' } : d
      ));

      try {
        const generatedImageUrl = await generateDesignForStyle(
          style,
          targetImage[0],
          brandImages,
          userPrompt
        );

        // Update state
        setDesigns(prev => prev.map(d => 
          d.styleId === style.id ? { ...d, status: 'completed', imageUrl: generatedImageUrl } : d
        ));

        // Update local tracker
        completedDesigns = completedDesigns.map(d => 
           d.styleId === style.id ? { ...d, status: 'completed', imageUrl: generatedImageUrl } : d
        );

      } catch (error: any) {
        console.error("Generation Error:", error);
        hasFailures = true;

        // Robust error checking for API Key issues
        const errorMsg = error?.message || JSON.stringify(error);
        const isAuthError = 
          errorMsg.includes('403') || 
          errorMsg.includes('PERMISSION_DENIED') || 
          errorMsg.includes('Requested entity was not found') || 
          errorMsg.includes('404');

        setDesigns(prev => prev.map(d => 
          d.styleId === style.id ? { ...d, status: 'failed' } : d
        ));

        // Update local tracker
        completedDesigns = completedDesigns.map(d => 
           d.styleId === style.id ? { ...d, status: 'failed' } : d
        );

        if (isAuthError) {
          setIsGenerating(false);
          setApiKeySelected(false);

          alert("API Access Error: The selected API Key does not have permission to use the luxury design models. Please select a valid paid API key.");

          if (window.aistudio && window.aistudio.openSelectKey) {
             await window.aistudio.openSelectKey();
             setApiKeySelected(true);
          }

          return; // Exit the loop entirely
        }
      }
    }

    // Save to History if we have at least one successful image
    const successfulCount = completedDesigns.filter(d => d.status === 'completed').length;
    if (successfulCount > 0) {
      const session: DesignSession = {
        id: Date.now().toString(),
        date: new Date().toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' }),
        prompt: userPrompt,
        originalImage: targetImage[0].url, // Note: storing the blob URL is temporary, ideally we store base64 but for quota reasons keeping it simple if currently active
        // However, for history to persist after refresh, we MUST use the base64 version
        designs: completedDesigns
      };

      // Swap the Blob URL for Base64 for the history storage to ensure it survives refresh
      // The `targetImage` in state has `base64` property
      const historySession = {
        ...session,
        originalImage: `data:${targetImage[0].file.type};base64,${targetImage[0].base64}`
      };

      saveToHistory(historySession);
    }

    setIsGenerating(false);
  };

  return (
    <div className="min-h-screen bg-gray-50 text-charcoal font-sans selection:bg-gold-200 selection:text-charcoal">

      {/* Header */}
      <header className="bg-white border-b border-gray-200 sticky top-0 z-50">
        <div className="max-w-7xl mx-auto px-6 h-20 flex items-center justify-between">
          <div className="flex items-center gap-3">
            <div className="bg-gold-500 p-2 rounded-sm text-white">
              <Palette size={24} />
            </div>
            <div>
              <h1 className="font-serif text-2xl font-bold tracking-tight text-charcoal">LUMINA</h1>
              <p className="text-[10px] uppercase tracking-[0.2em] text-gold-600">Hospitality Design AI</p>
            </div>
          </div>

          <div className="flex items-center gap-4">
             {!apiKeySelected && (
               <Button variant="text" onClick={handleSelectKey} className="text-xs">
                 <Key size={14} className="mr-1" /> Connect API Key
               </Button>
             )}
             {apiKeySelected && (
               <div className="flex items-center gap-2 text-green-700 text-xs font-semibold px-3 py-1 bg-green-50 rounded-full border border-green-100">
                 <ShieldCheck size={14} />
                 API Connected
               </div>
             )}
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main>
        {/* Hero / Upload Section */}
        <section className="bg-white pb-16 pt-12 border-b border-gray-200">
          <div className="max-w-4xl mx-auto px-6">

            <div className="text-center mb-12">
              <h2 className="font-serif text-4xl lg:text-5xl text-charcoal mb-4">Reimagine Your Corridor</h2>
