interface EditModalProps {
  isOpen: boolean;
  onClose: () => void;
  imageUrl: string;
}

export const EditModal: React.FC<EditModalProps> = ({ isOpen, onClose, imageUrl }) => {
  const [prompt, setPrompt] = useState('');
  const [isProcessing, setIsProcessing] = useState(false);
  const [editedImage, setEditedImage] = useState<string | null>(null);

  // Point selection state
  const [clickPoint, setClickPoint] = useState<{x: number, y: number} | null>(null);

  if (!isOpen) return null;

  const handleImageClick = (e: React.MouseEvent<HTMLDivElement>) => {
    // Only allow clicking if not already edited
    if (editedImage) return;

    const rect = e.currentTarget.getBoundingClientRect();
    const x = (e.clientX - rect.left) / rect.width;
    const y = (e.clientY - rect.top) / rect.height;
    setClickPoint({ x, y });
  };

  const clearPoint = (e: React.MouseEvent) => {
    e.stopPropagation();
    setClickPoint(null);
  };

  const handleEdit = async () => {
    if (!prompt.trim()) return;

    setIsProcessing(true);
    try {
      // Clean base64 string from original image url
      let base64 = imageUrl.split(',')[1];
      let finalPrompt = prompt;

      // If a point is selected, we need to draw a marker
      if (clickPoint) {
         // Create visual marker
         const markedBase64 = await addMarkerToImage(imageUrl, clickPoint);
         base64 = markedBase64;
         finalPrompt = `(Edit the object at the red dot location) ${prompt}`;
      }

      const result = await editDesign(base64, finalPrompt);
      setEditedImage(result);
    } catch (error) {
      console.error("Edit failed", error);
      alert("Failed to edit image. Please try again with a different prompt.");
    } finally {
      setIsProcessing(false);
    }
  };

  const addMarkerToImage = (imgSrc: string, point: {x: number, y: number}): Promise<string> => {
    return new Promise((resolve, reject) => {
      const img = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => {
        const canvas = document.createElement('canvas');
        canvas.width = img.naturalWidth;
        canvas.height = img.naturalHeight;
        const ctx = canvas.getContext('2d');
        if (!ctx) {
          reject(new Error("Could not get canvas context"));
          return;
        }

        ctx.drawImage(img, 0, 0);

        const x = point.x * img.naturalWidth;
        const y = point.y * img.naturalHeight;
        const radius = Math.max(img.naturalWidth * 0.02, 10);

        ctx.beginPath();
        ctx.arc(x, y, radius, 0, 2 * Math.PI);
        ctx.fillStyle = '#ff0000';
        ctx.fill();
        ctx.lineWidth = radius * 0.2;
        ctx.strokeStyle = '#ffffff';
        ctx.stroke();

        resolve(canvas.toDataURL('image/png').split(',')[1]);
      };
      img.onerror = reject;
      img.src = imgSrc;
    });
  };

  const handleReset = () => {
    setEditedImage(null);
    setPrompt('');
    setClickPoint(null);
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
