        {/* Header */}
        <div className="px-6 py-4 border-b border-gray-200 flex items-center justify-between bg-white z-10">
          <div className="flex items-center gap-2">
            <Wand2 className="text-gold-500" size={20} />
            <h3 className="font-serif text-xl text-charcoal font-bold">Refine & Edit Concept</h3>
          </div>
          <button 
            onClick={onClose}
            className="p-2 hover:bg-gray-100 rounded-full transition-colors text-gray-500"
          >
            <X size={20} />
          </button>
        </div>

        {/* Main Workspace */}
        <div className="flex-1 overflow-y-auto bg-gray-50 p-6">
          <div className="flex flex-col lg:flex-row gap-6 h-full items-stretch min-h-[400px]">

            {/* Original / Active Image */}
            <div className={`flex-1 flex flex-col ${editedImage ? 'hidden lg:flex' : ''}`}>
              <div className="mb-2 flex justify-between items-center">
                 <span className="text-xs font-bold uppercase tracking-wider text-gray-500">Original Concept</span>
              </div>

              <div 
                className={`flex-1 bg-gray-200 rounded-sm overflow-hidden relative shadow-inner group ${!editedImage ? 'cursor-crosshair' : ''}`}
                onClick={handleImageClick}
              >
                <img 
                  src={imageUrl} 
                  alt="Original" 
                  className="w-full h-full object-contain absolute inset-0" 
                />

                {/* Visual Hint (only if active) */}
                {!editedImage && !clickPoint && (
                    <div className="absolute top-4 left-4 bg-black/60 text-white px-3 py-1 rounded-full text-xs flex items-center gap-2 backdrop-blur-sm opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none z-20">
                        <MousePointer2 size={12} /> Click object to edit
                    </div>
                )}

                {/* Selected Marker */}
                {!editedImage && clickPoint && (
                    <div 
                        className="absolute w-6 h-6 -ml-3 -mt-3 rounded-full bg-red-500 border-2 border-white shadow-md animate-bounce z-10"
                        style={{ left: `${clickPoint.x * 100}%`, top: `${clickPoint.y * 100}%` }}
                    >
                         <button 
                            onClick={clearPoint}
                            className="absolute -top-6 -left-4 bg-black/80 text-white text-[10px] px-2 py-0.5 rounded opacity-0 group-hover:opacity-100 transition-opacity whitespace-nowrap"
                        >
                            Remove Target
                        </button>
                    </div>
                )}
              </div>
            </div>

            {/* Comparison Arrow (Desktop) */}
            {editedImage && (
              <div className="hidden lg:flex items-center justify-center">
                <ArrowRight className="text-gray-300" size={32} />
              </div>
            )}

            {/* Edited Result */}
            {editedImage && (
               <div className="flex-1 flex flex-col animate-fade-in">
                  <div className="mb-2 flex justify-between items-center">
                    <span className="text-xs font-bold uppercase tracking-wider text-gold-600">Refined Result</span>
                    <div className="flex gap-2">
                      <a 
                        href={editedImage}
                        download={`Lumina-Edit-${Date.now()}.png`}
                        className="text-xs flex items-center gap-1 text-charcoal hover:text-gold-600 font-bold"
                      >
                        <Download size={12} /> Download
                      </a>
                    </div>
                  </div>
                  <div className="flex-1 bg-gray-800 rounded-sm overflow-hidden relative shadow-xl border-2 border-gold-500/30">
                    <img 
                      src={editedImage} 
                      alt="Edited" 
                      className="w-full h-full object-contain absolute inset-0" 
                    />
                  </div>
               </div>
            )}
          </div>
        </div>

        {/* Footer / Controls */}
        <div className="p-6 bg-white border-t border-gray-200">
           <div className="max-w-4xl mx-auto flex flex-col gap-4">

              {!editedImage ? (
                <>
                  <div className="flex justify-between items-end">
                    <label className="text-sm font-bold text-charcoal uppercase tracking-wider">
                      How should this image change?
                    </label>
                    {clickPoint && (
                        <span className="text-xs text-red-500 font-bold flex items-center gap-1">
                            <MousePointer2 size={12} /> Target Locked
                        </span>
                    )}
                  </div>

                  <div className="flex gap-2">
                    <input 
                      type="text" 
                      className="flex-1 border border-gray-300 rounded-lg px-4 py-3 focus:ring-2 focus:ring-gold-400 focus:border-transparent outline-none bg-gray-50"
                      placeholder="e.g., 'Remove this', 'Change to leather', 'Make it brighter'..."
                      value={prompt}
                      onChange={(e) => setPrompt(e.target.value)}
                      onKeyDown={(e) => e.key === 'Enter' && handleEdit()}
                      autoFocus
                    />
                    <Button 
                      onClick={handleEdit} 
                      isLoading={isProcessing}
                      disabled={!prompt.trim()}
                      className="min-w-[140px]"
                    >
                      <Wand2 size={18} /> Apply Edit
                    </Button>
                  </div>
                </>
              ) : (
                <div className="flex items-center justify-between">
                   <div className="text-sm text-gray-500 italic">
                     Edit: "{prompt}"
