import { GoogleGenAI } from "@google/genai";
import { StyleDirection, FileData } from "../types";
import { SYSTEM_ROLE, ARCHITECTURAL_CONSTRAINTS, EDIT_SYSTEM_ROLE } from "../constants";

export const generateDesignForStyle = async (
  style: StyleDirection,
  targetImage: FileData,
  brandImages: FileData[],
  userPrompt: string
): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    // Construct the prompt
    const styleDescription = style.description.join('\n- ');

    const promptText = `
${SYSTEM_ROLE}

INPUT CONTEXT:
1. The FIRST image provided is the TARGET CORRIDOR structure.
2. The SUBSEQUENT images are BRAND REFERENCE style guides.

${ARCHITECTURAL_CONSTRAINTS}

STEP 3 — DESIGN TASK
Redesign the target corridor using the brand identity found in the reference images.

APPLY THIS SPECIFIC STYLE DIRECTION:
**${style.title.toUpperCase()}**
- ${styleDescription}

USER EDIT PROMPT (Apply intelligently):
"${userPrompt}"

STEP 6 — OUTPUT REQUIREMENTS (CRITICAL)
- Output EXACTLY 1 photorealistic image
- Keep the SAME camera angle as the original corridor
- No text, labels, or watermarks inside images
- Ultra-realistic lighting, materials, and shadows
- Hotel brochure / investor presentation quality
    `;

    const parts: any[] = [];

    // 1. Add Target Image (Structure)
    parts.push({
      inlineData: {
        data: targetImage.base64,
        mimeType: targetImage.file.type || 'image/png'
      }
    });

    // 2. Add Brand Images (Style References)
    brandImages.forEach(img => {
      parts.push({
        inlineData: {
          data: img.base64,
          mimeType: img.file.type || 'image/png'
        }
      });
    });

    // 3. Add Text Prompt
    parts.push({ text: promptText });

    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-image-preview',
      contents: {
        parts: parts
      },
      config: {
        imageConfig: {
          imageSize: "2K", // High quality for architecture
          aspectRatio: "16:9" // Or infer from image, but 16:9 is safe for cinematic corridor shots
        }
      }
    });

    // Extract image
    // Note: The response might contain multiple parts, we look for inlineData
    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("No image generated in response.");

  } catch (error) {
    console.error(`Error generating design for ${style.title}:`, error);
    throw error;
  }
};

export const editDesign = async (base64Image: string, prompt: string): Promise<string> => {
  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const parts = [
      {
        inlineData: {
          data: base64Image,
          mimeType: 'image/png' // Assuming PNG for canvas exports, or generic
        }
      },
      {
        text: prompt
      }
    ];

    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts },
      config: {
        systemInstruction: EDIT_SYSTEM_ROLE
      }
    });

    if (response.candidates?.[0]?.content?.parts) {
      for (const part of response.candidates[0].content.parts) {
        if (part.inlineData && part.inlineData.data) {
          return `data:image/png;base64,${part.inlineData.data}`;
        }
      }
    }

    throw new Error("No image generated.");
  } catch (e) {
      console.error("Edit Design Error:", e);
      throw e;
  }
};

